INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','easy','flashcard','What is the mechanism of action of phenytoin?','["Blocks voltage-gated sodium channels by selectively binding to the inactive state, slowing their recovery and preventing repetitive neuronal firing."]','A','Phenytoin stabilises the neuronal membrane without affecting normal low-frequency firing — it is use-dependent, acting preferentially on rapidly firing neurons.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','easy','flashcard','Name the classic dose-dependent CNS toxicity triad of phenytoin.','["Nystagmus, ataxia, and diplopia — occurring progressively as plasma levels rise above 20 mcg/mL. Mnemonic: NAD."]','A','At levels >40 mcg/mL, seizures paradoxically increase. Long-term effects include gingival hyperplasia, hirsutism, peripheral neuropathy, and osteoporosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','easy','flashcard','What is the therapeutic plasma level range for phenytoin?','["10-20 mcg/mL (approximately 40-80 micromol/L)."]','A','Phenytoin has a narrow therapeutic index and zero-order (saturable) kinetics — small dose increases can cause disproportionate rises in plasma concentration, risking toxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','medium','flashcard','What is the mechanism of sodium valproate and which seizure types is it used for?','["Multiple mechanisms: blocks Na+ channels, inhibits GABA transaminase (raising GABA levels), and blocks T-type Ca2+ channels. Used for focal, generalised tonic-clonic, absence, and myoclonic seizures — a true broad-spectrum antiepileptic."]','A','Valproate is also a first-line mood stabiliser in bipolar disorder. It inhibits CYP2C9 and epoxide hydrolase, raising levels of co-administered antiepileptics (e.g., lamotrigine, phenobarbital).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','medium','flashcard','Why is valproate contraindicated or used with extreme caution in women of childbearing age?','["Valproate is a potent teratogen — it causes neural tube defects (spina bifida), cognitive impairment in offspring, and other congenital abnormalities. It must be avoided in pregnancy wherever possible."]','A','High-dose folic acid (1-5 mg daily) must be prescribed before conception for any woman on antiepileptics. If valproate cannot be avoided, use the lowest effective dose and counsel about risks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','medium','flashcard','What is the mechanism of action of carbamazepine and what are its key drug interactions?','["Blocks voltage-gated Na+ channels. It is a potent inducer of CYP1A2, CYP2C, and CYP3A4 — it auto-induces its own metabolism and increases clearance of oral contraceptives, warfarin, and other antiepileptics."]','A','Carbamazepine is contraindicated in absence seizures — it worsens them. Monitor FBC (aplastic anaemia risk) and serum sodium (hyponatraemia in elderly).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','medium','flashcard','What is the mechanism of levetiracetam and why is it favoured for adjunct therapy?','["Binds to synaptic vesicle protein SV2A, modulating neurotransmitter release. Pharmacokinetic advantages: renally excreted unchanged, no CYP450 interactions, and minimal protein binding — resulting in very few drug-drug interactions."]','A','Levetiracetam is approved for focal, myoclonic, and primary generalised tonic-clonic seizures. Main side effect is mood alteration and irritability. Preferred in the elderly and in patients on multiple medications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','medium','flashcard','What is the drug of choice for absence seizures and what is its mechanism?','["Ethosuximide is first-line for typical absence seizures. It inhibits T-type (low-threshold) calcium channels in thalamic neurons, reducing the 3 Hz spike-and-wave discharge characteristic of absence epilepsy."]','A','Carbamazepine must NEVER be used for absence seizures — it worsens them. Lamotrigine is an alternative for absence seizures. Ethosuximide has no effect on other seizure types.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','hard','flashcard','What is the key drug interaction between lamotrigine and valproate, and what is the clinical significance?','["Valproate inhibits UGT1A4 (the enzyme that metabolises lamotrigine), approximately doubling lamotrigine plasma levels. This dramatically increases the risk of Stevens-Johnson syndrome. Lamotrigine must be titrated very slowly and at lower doses when co-prescribed with valproate."]','A','Slow titration of lamotrigine is always mandatory, but especially critical with concurrent valproate. Conversely, enzyme inducers such as carbamazepine lower lamotrigine levels, requiring higher doses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antiepileptics','hard','flashcard','What is the emergency treatment algorithm for status epilepticus?','["First-line: IV/IM/rectal benzodiazepine (IV lorazepam preferred; rectal diazepam if no IV access). Second-line: IV fosphenytoin, levetiracetam, or valproate. Refractory status: general anaesthesia with propofol, thiopental, or midazolam infusion."]','A','Phenytoin sodium must NEVER be given IM (causes tissue necrosis) — fosphenytoin is the preferred IV/IM formulation. Time is critical: prolonged uncontrolled seizures cause cumulative neuronal injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','easy','flashcard','What is the mechanism of action of SSRIs?','["SSRIs selectively block the serotonin reuptake transporter (SERT), increasing serotonin concentration in the synaptic cleft. They have 300-3000-fold greater selectivity for SERT over the norepinephrine transporter."]','A','SSRIs have little activity at muscarinic, alpha-adrenergic, or histamine H1 receptors — hence their superior tolerability compared to TCAs and MAOIs. Onset of therapeutic effect is typically 2-6 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','easy','flashcard','Name the six SSRIs and identify which has the longest half-life.','["The six SSRIs: fluoxetine, citalopram, escitalopram, fluvoxamine, paroxetine, sertraline. Fluoxetine has the longest half-life (~50 hours; active metabolite norfluoxetine ~10 days)."]','A','Fluoxetine''''s long half-life means lowest risk of discontinuation syndrome and requires a 5-week washout before starting an MAOI. Other SSRIs require only a 2-week washout.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','easy','flashcard','Name the classic features of serotonin syndrome.','["Triad: (1) mental status changes (agitation, confusion), (2) autonomic instability (hyperthermia, tachycardia, diaphoresis, hypertension), (3) neuromuscular abnormalities (clonus, myoclonus, hyperreflexia, muscle rigidity). Often triggered by SSRI + MAOI combination."]','A','Distinguish serotonin syndrome from NMS: serotonin syndrome has clonus/myoclonus and rapid onset (hours); NMS has lead-pipe rigidity, slower onset (days), and is triggered by antipsychotics not serotonergic drugs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','medium','flashcard','What is the mechanism of TCAs and what receptor blockade causes their major side effects?','["TCAs inhibit reuptake of both norepinephrine and serotonin. Additional receptor blockade causes: muscarinic blockade (dry mouth, urinary retention, constipation, blurred vision), alpha-1 blockade (orthostatic hypotension), H1 blockade (sedation), and Na+ channel blockade (cardiac arrhythmias in overdose)."]','A','TCA overdose causes life-threatening QRS-prolonging arrhythmias — treat with IV sodium bicarbonate (alkalinise to >7.5). TCAs are contraindicated in prostatic hyperplasia and angle-closure glaucoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','medium','flashcard','What foods must be avoided with MAOI antidepressants, and why?','["Tyramine-rich foods: aged cheeses, cured/smoked meats, liver, pickled fish, red wine, and fermented products. MAOIs inhibit gut MAO-A, so dietary tyramine is not metabolised, floods the circulation, and causes massive catecholamine release — resulting in a hypertensive crisis."]','A','Hypertensive crisis: severe occipital headache, stiff neck, tachycardia — can cause stroke or MI. MAOIs are last-line antidepressants due to this dangerous food and drug interaction profile.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','medium','flashcard','What washout period is required between stopping an MAOI and starting an SSRI?','["Minimum 2 weeks washout is required when switching between SSRIs and MAOIs in EITHER direction. Exception: fluoxetine must be stopped at least 5-6 weeks before starting an MAOI, because of its very long half-life and active metabolite norfluoxetine (~10 days)."]','A','Concurrent SSRI + MAOI use risks fatal serotonin syndrome. This washout requirement is one of the most high-yield drug safety facts in clinical pharmacology.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','medium','flashcard','What is the mechanism of mirtazapine and what are its characteristic side effects?','["Mirtazapine blocks central presynaptic alpha-2 receptors (increasing NE and 5-HT release), 5-HT2 receptors, and potently blocks histamine H1 receptors (causing sedation and weight gain). It does NOT cause sexual dysfunction — a significant advantage over SSRIs."]','A','Mirtazapine is useful for depressed patients with insomnia and weight loss. Its paradox: more sedating at lower doses (H1 blockade dominates) and less sedating at higher doses (NE stimulation counteracts sedation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','medium','flashcard','For which conditions beyond depression are SSRIs approved?','["OCD, panic disorder, PTSD, social anxiety disorder, GAD, premenstrual dysphoric disorder (PMDD), and bulimia nervosa (fluoxetine only). SSRIs are first-line for most anxiety disorders as well as depression."]','A','Mnemonic for SSRI indications beyond depression: OCD Panic PTSD Social GAD PMDD Bulimia. This versatility makes SSRIs uniquely valuable compared to other antidepressant classes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','hard','flashcard','What is the mechanism of bupropion and what are its unique clinical uses?','["Bupropion is a weak dopamine and norepinephrine reuptake inhibitor (NDRI). Uses: depression, smoking cessation (reduces nicotine cravings and withdrawal symptoms), and ADHD. Notable: very low rate of sexual dysfunction compared to SSRIs."]','A','Bupropion is CONTRAINDICATED in eating disorders (bulimia/anorexia) and seizure disorders due to dose-dependent seizure risk. Metabolised by CYP2B6. Does NOT inhibit serotonin reuptake — no serotonin syndrome risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antidepressants','hard','flashcard','What is SSRI discontinuation syndrome and which SSRI has the lowest risk?','["Abrupt SSRI withdrawal causes: flu-like symptoms, dizziness, electric shock sensations (brain zaps), agitation, insomnia, and irritability. Fluoxetine has the LOWEST risk due to its very long half-life (50 hours) and active metabolite norfluoxetine (~10 days) acting as a natural self-taper."]','A','Paroxetine has the HIGHEST risk of discontinuation syndrome (shortest half-life, no active metabolite). Always taper antidepressants gradually. The discontinuation syndrome is not a sign of addiction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','easy','flashcard','What is the key pharmacological difference between typical and atypical antipsychotics?','["Typical (1st-gen): primarily block dopamine D2 receptors — high EPS risk, lower metabolic risk. Atypical (2nd-gen): block both D2 and 5-HT2A receptors — lower EPS risk but higher metabolic side effects (weight gain, diabetes, dyslipidaemia)."]','A','The serotonin-dopamine balance hypothesis explains lower EPS with atypicals: 5-HT2A blockade in the nigrostriatal pathway counteracts D2 blockade, reducing extrapyramidal effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','easy','flashcard','Name the four types of extrapyramidal side effects (EPS) and their typical time of onset.','["Mnemonic DAPA: Dystonia (hours to days — painful muscle spasms), Akathisia (days to weeks — motor restlessness), Pseudo-Parkinsonism (weeks to months — bradykinesia, rigidity, tremor), tardive dyskinesia (months to years — involuntary oro-facial movements, possibly irreversible)."]','A','EPS result from D2 blockade in the nigrostriatal pathway. The risk is highest with high-potency typical antipsychotics (haloperidol) and lowest with low-potency atypicals (quetiapine, clozapine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','easy','flashcard','What is neuroleptic malignant syndrome (NMS) and how is it treated?','["NMS is a rare, life-threatening antipsychotic reaction: hyperthermia, lead-pipe muscle rigidity, altered consciousness, and autonomic instability (labile BP, tachycardia, diaphoresis). Treatment: stop the antipsychotic immediately, provide supportive care, give dantrolene (muscle relaxant), and bromocriptine (dopamine agonist)."]','A','NMS vs serotonin syndrome: NMS has lead-pipe rigidity (not clonus), slower onset (days), and is triggered by antipsychotics. Elevated creatine kinase (CK) is a key lab finding in NMS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','medium','flashcard','What metabolic monitoring parameters are required for patients on atypical antipsychotics?','["Monitor at baseline and at regular intervals: fasting glucose, HbA1c, fasting lipid profile, BMI and waist circumference, and blood pressure. Atypicals — especially clozapine, olanzapine, and quetiapine — cause weight gain, new-onset type 2 diabetes, and dyslipidaemia."]','A','Metabolic syndrome is a major cause of antipsychotic non-adherence. Aripiprazole and ziprasidone have the lowest metabolic burden; olanzapine and clozapine have the highest.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','medium','flashcard','What is the treatment for antipsychotic-induced acute dystonia?','["IV or IM anticholinergic drug: benztropine or diphenhydramine. Acute dystonia presents as painful sustained muscle contractions (oculogyric crisis, torticollis, opisthotonos) within hours to days of starting a potent typical antipsychotic."]','A','Akathisia (motor restlessness) responds better to propranolol (beta-blocker) or benzodiazepines than to anticholinergics. Memory rule: dystonia = anticholinergic; akathisia = propranolol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','medium','flashcard','Which antipsychotic requires mandatory white blood cell count monitoring and why?','["Clozapine — it causes agranulocytosis in approximately 1% of patients. Weekly WBC monitoring is mandatory for the first 6 months, then fortnightly. Clozapine is reserved for treatment-refractory schizophrenia (the 10-20% of patients who fail other antipsychotics)."]','A','Clozapine is the only antipsychotic with proven superior efficacy in treatment-resistant schizophrenia and for reducing suicidality. Despite its risks, it remains invaluable when other drugs have failed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','medium','flashcard','What is tardive dyskinesia and what drugs are approved for its treatment?','["Tardive dyskinesia (TD): involuntary repetitive movements — lip smacking, tongue protrusion, grimacing, choreiform limb movements — after months to years of antipsychotic use. Caused by dopamine receptor supersensitisation. Approved treatments: valbenazine and deutetrabenazine (VMAT2 inhibitors that deplete synaptic dopamine)."]','A','TD may be irreversible. Risk is highest with first-generation antipsychotics. Paradoxically, increasing the antipsychotic dose temporarily suppresses TD movements but worsens the underlying receptor supersensitisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','medium','flashcard','Which antipsychotics are partial agonists at the D2 receptor rather than pure antagonists?','["Aripiprazole, brexpiprazole, and cariprazine are D2 partial agonists and 5-HT1A partial agonists. They function as antagonists when dopamine is high (reducing positive symptoms) and as weak agonists when dopamine is low (reducing negative symptoms and lowering EPS risk)."]','A','D2 partial agonists have lower risk of EPS and hyperprolactinaemia compared to full D2 antagonists. Aripiprazole is also approved as an adjunct for treatment-resistant major depressive disorder.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','hard','flashcard','Which antipsychotic has the highest risk of QT prolongation?','["Thioridazine — it carries a black box warning for QT prolongation and the highest risk of torsades de pointes among antipsychotics. Ziprasidone and iloperidone also carry significant QTc prolongation warnings. Baseline ECG is recommended before starting any antipsychotic."]','A','All antipsychotics carry some QT prolongation risk. Avoid co-prescribing with other QT-prolonging drugs (macrolides, fluoroquinolones, methadone). Thioridazine is now rarely used due to this risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Antipsychotics','hard','flashcard','What are the positive and negative symptoms of schizophrenia and which antipsychotic class treats each better?','["Positive symptoms (hallucinations, delusions, disorganised thought): treated well by both typical and atypical antipsychotics via D2 blockade in the mesolimbic pathway. Negative symptoms (blunted affect, alogia, avolition, anhedonia): treated better by atypicals with 5-HT2A blockade — clozapine has the best evidence."]','A','First-generation antipsychotics are highly effective for positive symptoms but largely ineffective for negative symptoms. Treating negative symptoms remains one of the greatest unmet needs in schizophrenia pharmacotherapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','easy','flashcard','What is the mechanism of action of benzodiazepines at the GABA-A receptor?','["Benzodiazepines bind to an allosteric site on the GABA-A receptor (at the alpha-gamma subunit interface), potentiating GABA effects by INCREASING THE FREQUENCY of chloride channel opening. This causes Cl- influx, hyperpolarisation, and CNS depression."]','A','Key distinction: benzodiazepines increase FREQUENCY of Cl- channel opening; barbiturates increase DURATION. Neither activates the channel without GABA. Mnemonic: BZDs = Frequency; Barbs = Duration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','easy','flashcard','What drug reverses benzodiazepine overdose and what is its key limitation?','["Flumazenil — a competitive GABA-A receptor antagonist given IV. Key limitation: very short half-life (30-60 minutes), far shorter than most benzodiazepines — resedation commonly occurs and repeat dosing or an infusion may be required to maintain reversal."]','A','Flumazenil can precipitate seizures in benzodiazepine-dependent patients (by unmasking withdrawal) or in those who co-ingested a proconvulsant. It is NOT routinely used in mixed drug overdoses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','easy','flashcard','What are the five main clinical uses of benzodiazepines?','["(1) Anxiety disorders — GAD, panic disorder, phobias. (2) Insomnia — short-term only. (3) Status epilepticus — IV lorazepam or diazepam first-line. (4) Alcohol withdrawal — prevent seizures and delirium tremens. (5) Pre-procedural sedation and anterograde amnesia — midazolam."]','A','Benzodiazepines also relax skeletal muscle via spinal cord GABA-A alpha-2 receptors (diazepam for spasm). They reduce both REM sleep and slow-wave sleep with chronic use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','medium','flashcard','What is the mechanism of buspirone and how does it differ from benzodiazepines?','["Buspirone is a 5-HT1A receptor partial agonist used for GAD only. It has NO sedation, NO physical dependence, NO alcohol interaction, NO anticonvulsant or muscle relaxant properties, and NO abuse potential. Therapeutic onset is delayed 2-4 weeks."]','A','Buspirone is ideal for GAD in patients with a history of substance abuse or who need to remain alert. Patients previously on benzodiazepines may not feel buspirone is working due to absence of the familiar sedative calming effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','medium','flashcard','Which benzodiazepine is preferred for status epilepticus and why?','["IV lorazepam is preferred — it has a longer duration of brain anticonvulsant action than diazepam despite a similar half-life, because it redistributes less rapidly from the CNS to peripheral tissues. Rectal diazepam is used when IV access is unavailable."]','A','After lorazepam, a longer-acting second-line agent (fosphenytoin, levetiracetam, or valproate IV) is needed to prevent recurrence, as lorazepam''''s anticonvulsant effect wanes as it redistributes out of the brain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','medium','flashcard','What are the Z-drugs and how do they differ from benzodiazepines?','["Z-drugs (zopiclone, zolpidem, zaleplon) act at the same GABA-A benzodiazepine-binding site but are structurally distinct. They have more selective hypnotic effects (less anxiolytic, less muscle relaxant activity), shorter half-lives, and lower (but not absent) abuse potential."]','A','Z-drugs are preferred over long-acting benzodiazepines for insomnia in the elderly. However, they can cause complex sleep behaviours (sleepwalking, sleep-driving) and should only be used short-term.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','medium','flashcard','What are the features of benzodiazepine withdrawal syndrome?','["Symptoms: anxiety, tremor, insomnia, agitation, sweating, tachycardia, and rarely seizures or delirium. Short-acting benzodiazepines (triazolam, lorazepam) cause more rapid and severe withdrawal (onset within 24 hours); long-acting agents (diazepam, flurazepam) cause milder, delayed withdrawal (2-7 days)."]','A','Abrupt withdrawal from high-dose benzodiazepines can be life-threatening (seizures, delirium). Always taper gradually. Cross-tolerance between alcohol and benzodiazepines explains why benzodiazepines treat alcohol withdrawal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','medium','flashcard','Which benzodiazepine is used for anterograde amnesia during endoscopy or procedures?','["Midazolam — a short-acting water-soluble benzodiazepine given IV. It causes anterograde amnesia (inability to form new memories after administration) while the patient remains cooperative. It is the most commonly used benzodiazepine for procedural sedation and pre-anaesthetic premedication."]','A','Midazolam''''s amnesic effect is mediated via alpha-1 GABA-A receptors. Patients will not remember the procedure despite appearing awake — an important point when obtaining informed consent beforehand.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','hard','flashcard','Classify benzodiazepines by duration of action with one clinical use per category.','["Short-acting (t1/2 <6 h): triazolam, midazolam — procedural sedation. Intermediate-acting (6-24 h): lorazepam, temazepam, oxazepam (LTO — safe in liver disease, no active metabolites) — anxiety and maintenance insomnia. Long-acting (>24 h): diazepam, chlordiazepoxide, flurazepam — alcohol withdrawal, muscle spasm, and epilepsy."]','A','Short-acting agents cause MORE rebound insomnia and MORE severe withdrawal. Long-acting agents cause MORE daytime hangover and fall risk in the elderly. The LTO (Lorazepam, Temazepam, Oxazepam) group is preferred in liver disease and elderly patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Anxiolytics & Sedative-Hypnotics','hard','flashcard','Why are benzodiazepines safer in overdose than barbiturates?','["Benzodiazepines enhance GABA-mediated Cl- channel activity but CANNOT open channels independently — they require endogenous GABA, creating a functional ceiling. Barbiturates CAN directly open Cl- channels without GABA at high doses, causing profound CNS depression and fatal respiratory arrest at much lower overdose thresholds."]','A','The therapeutic index of benzodiazepines is far higher than barbiturates. Benzodiazepine overdose alone is rarely fatal; fatalities occur when combined with alcohol, opioids, or other CNS depressants.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','easy','flashcard','What is the therapeutic serum level range for lithium in acute mania versus maintenance?','["Acute mania: 0.8-1.2 mmol/L. Long-term maintenance (prophylaxis): 0.6-1.0 mmol/L. Toxic effects begin at >1.5 mmol/L; severe life-threatening toxicity at >2.0 mmol/L."]','A','Lithium has an extremely narrow therapeutic index. Serum levels are drawn 12 hours after the last dose (trough). Monitor weekly initially, then every 3-6 months once stable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','easy','flashcard','What are the early signs of lithium toxicity?','["Early toxicity (levels 1.5-2.0 mmol/L): coarse tremor, ataxia, slurred speech, nausea, vomiting, diarrhoea, confusion, and drowsiness. Severe toxicity (>2.0 mmol/L): convulsions, coma, renal failure, and cardiac arrhythmias."]','A','Distinguish fine tremor (common benign therapeutic side effect) from coarse tremor (early toxicity sign). Dehydration, NSAIDs, ACE inhibitors, and thiazide diuretics all raise lithium levels by reducing renal excretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','easy','flashcard','What routine monitoring is required for a patient on long-term lithium therapy?','["Serum lithium level, renal function (eGFR and creatinine), and thyroid function (TSH) — at baseline, after dose changes, and at minimum every 6 months. Long-term lithium causes nephrogenic diabetes insipidus (polyuria, polydipsia) and hypothyroidism."]','A','Lithium is entirely renally excreted — no hepatic metabolism occurs. Sodium depletion (low-salt diet, diuretics, dehydration) reduces renal lithium clearance, causing levels to rise into the toxic range.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','medium','flashcard','Why is lithium preferred over valproate in patients with hepatic impairment?','["Lithium is the only mood stabiliser that undergoes NO hepatic metabolism — it is entirely renally excreted unchanged. Valproate, carbamazepine, and lamotrigine all require significant hepatic metabolism and accumulate in liver disease, increasing toxicity risk."]','A','Conversely, lithium is dangerous in renal impairment and must be dose-reduced with close monitoring. Valproate may be preferred in that setting. The choice of mood stabiliser depends on the patient''''s organ function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','medium','flashcard','Which antiepileptic drugs are approved as mood stabilisers for bipolar disorder?','["Valproate (divalproex) — effective for acute mania and maintenance. Carbamazepine — effective for acute mania. Lamotrigine — particularly effective for prevention of bipolar DEPRESSION (less effective for acute mania). All three are approved mood stabilisers."]','A','Lamotrigine is the only antiepileptic with strong evidence for bipolar depression prevention. Very slow titration is mandatory due to rash and Stevens-Johnson syndrome risk, especially with concurrent valproate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','medium','flashcard','Name five common or notable side effects of lithium at therapeutic doses.','["(1) Fine hand tremor — most common. (2) Polyuria and polydipsia — nephrogenic diabetes insipidus. (3) Weight gain and oedema. (4) Hypothyroidism — with long-term use. (5) Cognitive dulling and memory impairment. Less common: acne, psoriasis, leukocytosis."]','A','Mnemonic for lithium side effects: WHEN — Weight gain, Hypothyroidism, ECG changes (T-wave flattening), Nephrogenic DI, tremor. Monitor thyroid and renal function throughout treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','medium','flashcard','Which drugs precipitate lithium toxicity by reducing renal lithium clearance?','["NSAIDs (reduce prostaglandin-mediated renal blood flow), thiazide diuretics (cause Na+ depletion, increasing lithium reabsorption in proximal tubule), and ACE inhibitors/ARBs (reduce GFR). Dehydration and a low-sodium diet also significantly raise lithium levels."]','A','Loop diuretics (furosemide) are safer with lithium than thiazides because they act on the loop of Henle rather than the proximal tubule where lithium reabsorption occurs. However, diuretic-induced dehydration can still raise levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','medium','flashcard','What is the proposed mechanism of the anti-manic effect of lithium?','["The exact mechanism is unknown. Proposed mechanisms: inhibition of inositol monophosphatase (depleting inositol, a second messenger precursor), inhibition of glycogen synthase kinase-3 (GSK-3), and modulation of multiple neurotransmitter systems including decreased dopamine and norepinephrine turnover."]','A','The delayed therapeutic onset (weeks) suggests downstream cellular adaptations rather than an immediate receptor effect underlie lithium''''s mood-stabilising properties.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','hard','flashcard','What is the treatment for acute lithium toxicity?','["Stop lithium immediately. IV hydration with 0.9% NaCl (restores volume and promotes renal lithium excretion). Haemodialysis for severe toxicity (level >3.0 mmol/L or severe symptoms at lower levels). There is no specific antidote for lithium."]','A','Haemodialysis is highly effective because lithium has a small volume of distribution and is not protein-bound. Lithium redistributes from tissues into blood after dialysis (rebound), so repeated sessions may be needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Mood Stabilisers','hard','flashcard','What is the teratogenic risk of mood stabilisers and which is considered safest in pregnancy?','["Valproate: highest risk — neural tube defects and cognitive impairment in offspring (avoid if at all possible). Carbamazepine: moderate risk — neural tube defects. Lithium: Ebstein''''s anomaly (cardiac malformation) — low absolute risk but still a concern. Lamotrigine: considered the safest mood stabiliser in pregnancy, though not risk-free."]','A','All women of childbearing potential on mood stabilisers should take high-dose folic acid (5 mg/day) pre-conception. A multidisciplinary team approach (psychiatrist + obstetrician) is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','easy','flashcard','Why is levodopa always co-administered with carbidopa?','["Carbidopa is a peripheral DOPA decarboxylase inhibitor. Without it, most levodopa is converted to dopamine in the periphery before reaching the brain, causing nausea, vomiting, and cardiovascular side effects. Carbidopa reduces the required levodopa dose by 4-5-fold and minimises peripheral adverse effects."]','A','Dopamine cannot cross the blood-brain barrier — levodopa (its precursor) can, and is converted to dopamine in surviving substantia nigra neurons. Carbidopa itself does not cross the BBB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','easy','flashcard','What are the cardinal motor features of Parkinson''''s disease — the TRAP mnemonic?','["TRAP: Tremor (resting, pill-rolling, 4-6 Hz), Rigidity (cogwheel or lead-pipe), Akinesia/bradykinesia (slowness of movement), Postural instability. Caused by loss of dopaminergic neurons in the substantia nigra pars compacta."]','A','The dopamine-acetylcholine imbalance in the neostriatum is key: dopamine loss leads to relative cholinergic excess and motor symptoms. This is why anticholinergic drugs (benztropine) can help early-stage symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','easy','flashcard','What is the wearing-off phenomenon with levodopa-carbidopa therapy?','["After 3-5 years of therapy, as more dopaminergic neurons die, end-of-dose deterioration occurs — motor symptoms return before the next dose is due. Managed by: more frequent dosing, adding a COMT inhibitor (entacapone) or a selective MAO-B inhibitor (selegiline or rasagiline) to extend levodopa effect."]','A','The on-off phenomenon is more unpredictable — abrupt switches between mobility and immobility unrelated to dose timing. It reflects dopamine receptor sensitivity changes and is harder to manage than wearing-off.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','medium','flashcard','What is the mechanism of selegiline and why is it safer than non-selective MAOIs?','["Selegiline selectively inhibits MAO-B (which metabolises dopamine in the striatum), increasing dopamine levels. At therapeutic doses it does NOT inhibit MAO-A (which metabolises noradrenaline and serotonin in the gut), so there is no significant tyramine cheese reaction — unlike non-selective MAOIs."]','A','Selegiline is metabolised to amphetamine and methamphetamine (can cause insomnia if taken after midday). Rasagiline, another MAO-B inhibitor, is not metabolised to amphetamine — a clinical advantage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','medium','flashcard','What is the mechanism of entacapone and tolcapone and when are they used?','["Both are COMT (catechol-O-methyltransferase) inhibitors. COMT converts levodopa to 3-O-methyldopa (3-OMD), which competes with levodopa for CNS uptake. Inhibiting COMT reduces 3-OMD, increasing levodopa availability to the brain. Used as adjuncts with levodopa-carbidopa to reduce the wearing-off phenomenon."]','A','Tolcapone is associated with fatal hepatic necrosis — LFTs must be monitored and it is reserved for patients who failed entacapone. Entacapone (safer) has largely replaced tolcapone in clinical practice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','medium','flashcard','Name four non-ergot dopamine agonists used in Parkinson''''s disease and their routes of administration.','["Pramipexole (oral), ropinirole (oral), rotigotine (transdermal patch — once daily, providing steady drug levels), apomorphine (subcutaneous injection — for acute hypomobility off episodes). These have longer action than levodopa and lower early dyskinesia risk."]','A','Dopamine agonists delay need for levodopa in early PD. Side effects include hallucinations, impulse control disorders (gambling, hypersexuality), somnolence, and orthostatic hypotension. Ergot derivative bromocriptine carries additional fibrosis and vasospasm risks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','medium','flashcard','What is the mechanism of amantadine in Parkinson''''s disease?','["Amantadine has multiple mechanisms: increases dopamine release from presynaptic terminals, blocks NMDA glutamate receptors, and has mild anticholinergic activity. It is less efficacious than levodopa but has fewer side effects. It is also specifically used to treat levodopa-induced dyskinesias."]','A','Amantadine was accidentally discovered to have antiparkinsonian effects when it reduced symptoms in a patient using it as an antiviral. Notable adverse effect: livedo reticularis (mottled purple skin) and ankle oedema.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','medium','flashcard','What vitamin interaction must be avoided with levodopa and why?','["Pyridoxine (vitamin B6) increases peripheral DOPA decarboxylase activity, accelerating conversion of levodopa to dopamine in the periphery before it crosses the blood-brain barrier — reducing levodopa''''s CNS efficacy. This interaction is abolished when carbidopa is co-administered."]','A','High-protein meals also reduce levodopa efficacy by competing for the same intestinal and blood-brain barrier amino acid transporter. Levodopa should be taken 30 minutes before meals on an empty stomach.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','hard','flashcard','Which antipsychotics can safely manage levodopa-induced psychosis in Parkinson''''s disease?','["Low-dose quetiapine or clozapine — both have low D2 affinity in the striatum and are less likely to worsen motor symptoms. Pimavanserin (a 5-HT2A inverse agonist with NO D2 receptor activity) is specifically FDA-approved for Parkinson''''s disease psychosis."]','A','Most antipsychotics (especially haloperidol and risperidone) are CONTRAINDICATED in PD — they block dopamine receptors and dramatically worsen Parkinsonian motor symptoms. This is a high-stakes clinical pitfall.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Parkinson''''s Disease Drugs','hard','flashcard','What is the role of anticholinergic drugs (benztropine, trihexyphenidyl) in Parkinson''''s disease?','["Anticholinergics reduce the relative cholinergic excess in the striatum caused by dopamine depletion, restoring the dopamine-acetylcholine balance. Most useful for tremor in early-stage PD in younger patients. They are much less efficacious than levodopa for rigidity and bradykinesia."]','A','Anticholinergics are avoided in the elderly due to CNS effects (confusion, hallucinations, memory loss) and peripheral effects (urinary retention, constipation, dry mouth). CONTRAINDICATED in glaucoma and prostatic hyperplasia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','easy','flashcard','What are the three pathological hallmarks of Alzheimer''''s disease?','["(1) Beta-amyloid plaques (senile plaques) — extracellular deposits. (2) Neurofibrillary tangles (hyperphosphorylated tau protein) — intracellular. (3) Progressive loss of cortical cholinergic neurons, especially in the nucleus basalis of Meynert."]','A','The cholinergic hypothesis underpins drug therapy: loss of cholinergic neurons leads to impaired memory. Current drugs are palliative — none alter the underlying neurodegenerative process.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','easy','flashcard','Name the three cholinesterase inhibitors approved for Alzheimer''''s disease.','["Donepezil (mild-to-severe AD — once daily), rivastigmine (mild-to-moderate AD; also for Parkinson''''s dementia; available as transdermal patch), and galantamine (mild-to-moderate AD; also potentiates nicotinic ACh receptors)."]','A','All three increase synaptic acetylcholine via AChE inhibition. Common cholinergic side effects: nausea, vomiting, diarrhoea, bradycardia. Donepezil is given once daily and is the most widely prescribed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','easy','flashcard','What is the mechanism of memantine and for which stage of Alzheimer''''s disease is it indicated?','["Memantine is an NMDA receptor antagonist. It blocks excessive Ca2+ influx from pathologically overstimulated NMDA receptors (excitotoxicity), helping protect neurons. It is indicated for MODERATE-TO-SEVERE Alzheimer''''s disease."]','A','Memantine is often combined with donepezil in moderate-to-severe AD for additive benefit via complementary mechanisms. Its adverse effects (confusion, agitation) can be indistinguishable from the symptoms of AD itself.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','medium','flashcard','Which cholinesterase inhibitor is available as a transdermal patch and what is its unique clinical advantage?','["Rivastigmine — available as a once-daily transdermal patch. Advantages: avoids GI side effects (nausea, vomiting) that are common with oral formulations, provides steady drug levels, and is the ONLY cholinesterase inhibitor also approved for Parkinson''''s disease dementia."]','A','Rivastigmine is hydrolysed directly by AChE (not CYP450), resulting in fewer drug-drug interactions than donepezil or galantamine. It also inhibits butyrylcholinesterase (BuChE).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','medium','flashcard','What are the common adverse effects of cholinesterase inhibitors and how are they managed?','["Cholinergic side effects: nausea, vomiting, diarrhoea (most common), anorexia, weight loss, bradycardia, and muscle cramps. Management: start at low dose and titrate slowly, take oral formulations with food, or switch to rivastigmine transdermal patch to reduce GI side effects."]','A','Bradycardia is clinically important — cholinesterase inhibitors should be used cautiously in patients with sick sinus syndrome or significant heart block. They can also worsen or precipitate peptic ulcers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','medium','flashcard','What is the unique dual mechanism of galantamine?','["Galantamine has two mechanisms: (1) reversible competitive inhibition of AChE, AND (2) positive allosteric modulation of nicotinic acetylcholine receptors (nAChRs). The nicotinic receptor potentiation may provide additional cognitive benefit beyond simple AChE inhibition."]','A','All three cholinesterase inhibitors provide modest, temporary cognitive benefit — slowing the rate of decline rather than restoring function. None cure or halt Alzheimer''''s disease progression.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','medium','flashcard','Can memantine be combined with a cholinesterase inhibitor in Alzheimer''''s disease?','["Yes — memantine and donepezil (or other cholinesterase inhibitors) can and should be combined in moderate-to-severe AD. They work via complementary mechanisms (glutamatergic NMDA blockade vs. cholinergic enhancement), and combination therapy shows modest additive cognitive benefit."]','A','Memantine is well tolerated, renally excreted, and requires dose adjustment in renal impairment. Its adverse effects — confusion, agitation, dizziness — can be difficult to distinguish from underlying dementia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','medium','flashcard','Why is rivastigmine used with caution in Parkinson''''s disease despite being the only approved treatment for Parkinson''''s dementia?','["Rivastigmine increases synaptic ACh levels — this can worsen Parkinsonian motor symptoms (especially tremor) by further disrupting the dopamine-acetylcholine balance in the striatum. A thorough risk-benefit discussion is required with the patient and caregiver before initiating."]','A','Despite the tremor risk, rivastigmine is the ONLY approved treatment for Parkinson''''s disease dementia, making careful monitoring essential rather than avoidance. Monitor closely for worsening of motor symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','hard','flashcard','What is the excitotoxicity hypothesis in Alzheimer''''s disease and how does memantine address it?','["In AD, chronic low-level glutamate leakage tonically stimulates NMDA receptors, causing constant Ca2+ influx. This overwhelms intracellular Ca2+ buffers, activates destructive proteases and mitochondrial death pathways, leading to apoptosis. Memantine blocks this pathological tonic stimulation while allowing normal fast synaptic glutamate transmission needed for memory formation."]','A','Memantine preferentially blocks pathological low-level tonic NMDA activation over physiological fast phasic activation, due to its voltage-dependence and faster receptor off-rate — preserving LTP and memory.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Alzheimer''''s Disease Drugs','hard','flashcard','Which cholinesterase inhibitor has NO clinically significant CYP450 drug interactions and why?','["Rivastigmine — it is hydrolysed directly by acetylcholinesterase (its target enzyme), producing a carbamylated metabolite, and does NOT use CYP450 enzymes. Donepezil and galantamine ARE CYP450 substrates (CYP2D6 and CYP3A4) and are susceptible to interactions with CYP inhibitors and inducers."]','A','This makes rivastigmine a safer choice in patients with polypharmacy. Elderly patients with dementia commonly take many medications metabolised by CYP450, making drug-drug interactions a major clinical concern.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','easy','flashcard','What are the three main opioid receptor types and their primary clinical effects?','["Mu (MOR): analgesia, euphoria, respiratory depression, constipation, miosis, physical dependence — the main analgesic receptor. Kappa (KOR): analgesia, sedation, dysphoria. Delta (DOR): analgesia, mood modulation. All three are Gi-coupled receptors that reduce cAMP, increase K+ efflux, and decrease Ca2+ influx."]','A','Most clinical opioids (morphine, fentanyl, codeine) act primarily at mu receptors. The inhibition of Ca2+ influx and increase in K+ efflux reduces neuronal firing and transmitter release in dorsal horn pain pathways.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','easy','flashcard','What is the classic clinical triad of opioid overdose?','["Pinpoint pupils (miosis), respiratory depression (reduced rate and depth), and decreased consciousness/coma. Respiratory depression — caused by reduced responsiveness of medullary respiratory centre neurons to CO2 — is the most common cause of death in acute opioid overdose."]','A','Pupils are MIOTIC (pinpoint) in opioid overdose — in contrast to most other causes of coma which cause pupil dilation. Little tolerance develops to miosis or constipation, even with chronic opioid use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','easy','flashcard','How does naloxone reverse opioid overdose and what is its key pharmacokinetic limitation?','["Naloxone is a competitive mu/kappa/delta opioid receptor antagonist with ~10-fold higher affinity for mu than kappa receptors. It reverses respiratory depression within 1-2 minutes of IV administration. KEY LIMITATION: half-life of only 30-81 minutes — far shorter than most opioids — so resedation may occur."]','A','Available as IV, IM, subcutaneous, and intranasal (Narcan) formulations. In buprenorphine overdose, much higher and repeated doses are needed due to buprenorphine''''s extremely high mu receptor affinity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','medium','flashcard','Why is fentanyl 100 times more potent than morphine and what are its key clinical uses?','["Fentanyl is highly lipophilic — it crosses the blood-brain barrier rapidly, producing fast onset and short duration. Clinical uses: IV anaesthetic analgesia, epidural labour analgesia, transdermal patches for chronic severe pain (12-hour delayed onset), and transmucosal or nasal formulations for cancer breakthrough pain."]','A','The transdermal fentanyl patch is CONTRAINDICATED in opioid-naive patients and acute/post-operative pain. Fentanyl is metabolised by CYP3A4 — inhibitors (e.g., azole antifungals) can cause dangerous toxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','medium','flashcard','What is the mechanism by which codeine produces analgesia, and what is the risk in ultrarapid metabolisers?','["Codeine is a prodrug converted to active morphine by CYP2D6. Ultrarapid CYP2D6 metabolisers (genetic variant common in North African populations) convert codeine to morphine at very high rates, risking morphine accumulation, overdose, and fatal respiratory depression even at standard therapeutic doses."]','A','Codeine is contraindicated in children post-tonsillectomy/adenoidectomy due to fatal respiratory depression in ultrarapid metabolisers. Poor CYP2D6 metabolisers get no analgesia from codeine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','medium','flashcard','What are the signs and symptoms of opioid withdrawal syndrome?','["Anxiety, yawning, lacrimation, rhinorrhoea, piloerection (gooseflesh), MYDRIASIS (dilated pupils — opposite of overdose), diaphoresis, myalgia, abdominal cramping, diarrhoea, tachycardia, hypertension, and insomnia. Onset and duration depend on the opioid''''s half-life."]','A','Opioid withdrawal is very unpleasant but rarely life-threatening — unlike alcohol or benzodiazepine withdrawal (which can cause fatal seizures). Methadone withdrawal is milder but more protracted (days to weeks) due to long half-life.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','medium','flashcard','What is opioid-induced constipation (OIC) and how is it managed?','["Opioids bind to peripheral mu receptors in the GI tract, reducing intestinal motility, increasing circular smooth muscle tone, increasing anal sphincter tone, and decreasing secretions. Critically, TOLERANCE DOES NOT DEVELOP to constipation. First-line: stimulant laxatives (senna). Prescription: methylnaltrexone, naloxegol (peripheral mu antagonists that do not cross the BBB)."]','A','Docusate (stool softener alone) is INEFFECTIVE for OIC. A stimulant laxative must be prescribed prophylactically with every opioid prescription. Docusate + senna combination products are widely used.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','medium','flashcard','What makes methadone unique among opioid analgesics?','["Methadone is a full mu agonist, NMDA receptor antagonist, and norepinephrine/serotonin reuptake inhibitor — making it effective for both nociceptive and neuropathic pain. It has a very long and variable half-life (12-150 hours) but a shorter duration of analgesia (4-8 hours), creating an accumulation and overdose risk."]','A','Methadone prolongs QTc interval — baseline and periodic ECG monitoring required. Dose adjustments only every 5-7 days. Its numerous CYP450 interactions and variable pharmacokinetics make it a drug for experienced prescribers only.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','hard','flashcard','What is buprenorphine''''s pharmacodynamic profile and why is it used for opioid use disorder?','["Buprenorphine is a partial mu agonist (high affinity, low intrinsic activity) and kappa antagonist. Its partial agonism creates a ceiling effect on respiratory depression and euphoria, reducing abuse potential. Very high mu affinity means it displaces full agonists, potentially precipitating withdrawal if given too early. Approved for pain and opioid use disorder (office-based treatment)."]','A','Suboxone = buprenorphine + naloxone (4:1). Naloxone is added to deter IV abuse — sublingual naloxone has minimal systemic absorption but IV injection precipitates withdrawal. Unlike methadone for OUD (specialist clinic only), buprenorphine can be prescribed in office-based settings.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Opioid Analgesics','hard','flashcard','Why is meperidine avoided in elderly patients and those with renal impairment?','["Meperidine is metabolised to normeperidine (an active metabolite) that is renally excreted. In renal impairment and the elderly, normeperidine accumulates, causing neuroexcitatory toxicity: tremors, myoclonus, hyperreflexia, and seizures — NOT reversible with naloxone. Meperidine + MAOIs causes serotonin syndrome or hypertensive crisis."]','A','Meperidine should only be used for short-term (max 48 hours) management. Its anticholinergic properties increase delirium risk in the elderly. Avoid in renal failure, elderly patients, and patients on MAOIs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','easy','flashcard','What is the mechanism of action of local anaesthetics?','["Local anaesthetics block voltage-gated sodium (Na+) channels on neuronal membranes, preventing the transient Na+ influx required to generate an action potential. They penetrate the membrane in the unionised (free base) form and block the channel from the intracellular side in the ionised form."]','A','Local anaesthetics are use-dependent — they block channels more effectively when neurons fire rapidly, as in pain signalling. This allows selective reduction of pain at low concentrations without blocking all nerve functions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','easy','flashcard','What is the chemical difference between ester and amide local anaesthetics? Give two examples of each.','["Esters: linked by an ester bond, metabolised by plasma pseudocholinesterase. Examples: procaine, tetracaine, benzocaine, chloroprocaine. Amides: linked by an amide bond, metabolised in the liver by CYP450 enzymes. Examples: lidocaine, bupivacaine, ropivacaine, mepivacaine."]','A','Memory trick: amide local anaesthetics have TWO i''''s in their name (lIdocaIne, bupIvacaIne). Esters have ONE i (procaine, tetracaine). Esters produce PABA on metabolism — the allergenic component.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','easy','flashcard','Why is epinephrine added to local anaesthetic solutions?','["Epinephrine causes local vasoconstriction, reducing systemic absorption of the local anaesthetic. This: (1) prolongs duration of action by retaining the drug at the injection site, (2) reduces peak plasma levels and systemic toxicity, and (3) decreases bleeding at the procedural site."]','A','Epinephrine-containing local anaesthetics must NOT be injected into digits, penis, ear lobe, or nose — vasoconstriction can cause ischaemia and tissue necrosis. Also avoid in patients with severe cardiovascular disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','medium','flashcard','Which nerve fibres are most sensitive to local anaesthetics and in what order are functions lost?','["Smallest and unmyelinated fibres are most sensitive. Order of blockade: pain and temperature first (C fibres and A-delta) → autonomic function (B fibres) → touch and pressure → motor function last (large myelinated A-alpha fibres are most resistant to blockade)."]','A','Differential block underpins epidural analgesia in labour — the patient loses pain before touch, before motor function. This allows childbirth analgesia while maintaining the ability to push.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','medium','flashcard','What primarily determines the onset of action of a local anaesthetic?','["Primarily the pKa. Agents with a lower pKa (closer to physiological pH 7.4) have more drug in the unionised free-base form at physiological pH, allowing faster membrane penetration and quicker onset. Infected tissue (lower local pH) reduces ionisation and delays or prevents onset."]','A','Lidocaine (pKa 7.9) has fast onset; bupivacaine (pKa 8.1) has slower onset but longer duration. Duration depends mainly on lipid solubility and protein binding. Always aspirate before each injection to detect inadvertent intravascular placement.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','medium','flashcard','What are the features of local anaesthetic systemic toxicity (LAST) and its treatment?','["Early CNS signs: tinnitus, circumoral numbness, metallic taste, dizziness, agitation. Severe: seizures and coma. Cardiovascular: arrhythmias, myocardial depression, cardiovascular collapse. Treatment: stop injection, airway management, IV benzodiazepines for seizures, and IV 20% lipid emulsion (lipid rescue therapy)."]','A','Bupivacaine has the highest cardiotoxicity risk. Ropivacaine (the S-enantiomer equivalent) has less cardiotoxicity and is preferred for major nerve blocks. Lipid emulsion must be available wherever regional anaesthesia is performed.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','medium','flashcard','What is the allergy profile of ester versus amide local anaesthetics?','["Esters produce para-aminobenzoic acid (PABA) on metabolism — PABA is the allergenic component. Allergy to ONE ester means allergy to ALL esters (cross-reactivity via PABA). True allergy to amide local anaesthetics is exceedingly rare. A patient allergic to an ester CAN safely receive an amide, and vice versa."]','A','Many reported local anaesthetic allergies are actually reactions to co-administered epinephrine (tachycardia, anxiety) or preservatives. True IgE-mediated allergy to amide local anaesthetics is very rare.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','medium','flashcard','Name four amide local anaesthetics and rank them by approximate duration of action.','["Short duration (~1-2 hours): lidocaine and mepivacaine. Long duration (4-8+ hours): bupivacaine and ropivacaine. Bupivacaine is the longest-acting and most commonly used for epidural and spinal analgesia. Ropivacaine has lower cardiotoxicity than bupivacaine."]','A','Duration correlates with lipid solubility and protein binding. Bupivacaine is 95% protein-bound — it is released slowly from the Na+ channel, prolonging its effect. Adding epinephrine extends the duration of all local anaesthetic agents.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','hard','flashcard','What is the clinical significance of pseudocholinesterase deficiency for ester local anaesthetics?','["Ester local anaesthetics are hydrolysed by plasma pseudocholinesterase. In pseudocholinesterase-deficient patients (autosomal recessive genetic variant), ester hydrolysis is impaired, leading to prolonged action and systemic toxicity. This is the same enzyme that metabolises succinylcholine — deficient patients also experience prolonged neuromuscular paralysis (suxamethonium apnoea)."]','A','Pseudocholinesterase deficiency is clinically silent until exposure to relevant drugs. It is detected by the dibucaine number test. Amide local anaesthetics are safe alternatives in affected patients.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Local Anaesthetics','hard','flashcard','What is the non-anaesthetic clinical use of lidocaine and what is the mechanism?','["Lidocaine (lignocaine) is a Class IB antiarrhythmic for ventricular arrhythmias (particularly post-MI ventricular tachycardia). It blocks fast Na+ channels in cardiac muscle, suppressing abnormal automaticity in ischaemic myocardium. It is use-dependent — preferentially binds inactivated Na+ channels in depolarised/ischaemic tissue."]','A','Lidocaine is given IV for ventricular arrhythmias in emergency settings. It does not significantly depress normal cardiac conduction (selective for abnormally firing tissue). CNS toxicity (seizures, confusion) can occur at high plasma concentrations.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','easy','flashcard','What is the primary mechanism of action of cocaine in the CNS?','["Cocaine blocks reuptake transporters for dopamine, norepinephrine, and serotonin (monoamine reuptake inhibitor), flooding the synapse with these neurotransmitters. The intense euphoria is primarily due to dopamine accumulation in the mesolimbic reward pathway (nucleus accumbens)."]','A','Cocaine also functions as a local anaesthetic (Na+ channel blocker) and was the original topical local anaesthetic used in ophthalmology. It is still used clinically for nasal surgery due to combined anaesthetic and vasoconstrictive properties.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','easy','flashcard','How does the mechanism of amphetamine differ from cocaine?','["Both raise synaptic monoamine levels but via different mechanisms. Cocaine BLOCKS REUPTAKE TRANSPORTERS passively. Amphetamine actively REVERSES the transporters (causing release of intracellular stored dopamine, NE, and serotonin into the synapse) AND inhibits MAO. Amphetamine effects last longer (4-6 hours vs ~1 hour for cocaine)."]','A','The active reversal of transporters by amphetamine is independent of nerve firing, making amphetamine''''s dopamine release independent of vesicular stores at later stages of use. Methamphetamine is even more potent at this mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','easy','flashcard','What is the cornerstone treatment for acute cocaine or amphetamine toxicity in the ED?','["IV benzodiazepines (e.g., lorazepam) — they reduce agitation, treat seizures, help cool the patient by reducing psychomotor agitation, and lower blood pressure. Beta-blockers are CONTRAINDICATED — they cause unopposed alpha-adrenergic stimulation, worsening hypertension and coronary vasospasm."]','A','Hyperthermia is a major cause of death in cocaine and amphetamine toxicity — aggressive active cooling is essential. Cocaine-induced chest pain requires ECG to exclude MI; beta-blockers remain contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','medium','flashcard','What is the psychoactive component of cannabis and what receptor does it act on?','["Delta-9-tetrahydrocannabinol (THC) — the main psychoactive compound in Cannabis sativa. It acts as a partial agonist at CB1 cannabinoid receptors (brain/CNS) and CB2 receptors (periphery/immune system). Effects: euphoria, relaxation, impaired short-term memory, hyperphagia, tachycardia, and decreased muscle coordination."]','A','THC impairs short-term memory via GABA effects in the hippocampus — particularly harmful in adolescents (17% develop dependence). It can be detected in urine for up to 3 months in heavy chronic users.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','medium','flashcard','What are the features of alcohol withdrawal syndrome and how is it treated?','["Alcohol withdrawal — from loss of GABA enhancement and rebound NMDA/glutamate excitation: tremor, tachycardia, hypertension, sweating, and insomnia (onset 6-24 hours). Severe: seizures (12-48 hours), delirium tremens (48-72 hours — confusion, hallucinations, autonomic instability). Treatment: benzodiazepines, thiamine before glucose, and supportive care."]','A','Alcohol withdrawal is LIFE-THREATENING — unlike opioid withdrawal. CIWA-Ar score guides benzodiazepine dosing. Thiamine must ALWAYS be given before IV glucose in alcohol-dependent patients to prevent Wernicke''''s encephalopathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','medium','flashcard','What is the mechanism of disulfiram in treating alcohol use disorder?','["Disulfiram inhibits aldehyde dehydrogenase (ALDH), blocking the second step of alcohol metabolism. When alcohol is consumed, acetaldehyde accumulates, causing the disulfiram reaction: severe flushing, headache, nausea, vomiting, tachycardia, and hypotension — a powerful aversive response that deters alcohol consumption."]','A','Patients must avoid hidden alcohol in foods, sauces, mouthwashes, and some medications. Disulfiram-like reactions can also be caused by metronidazole, certain cephalosporins, and tinidazole when combined with alcohol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','medium','flashcard','Name the therapeutic uses of amphetamines and methylphenidate.','["(1) ADHD — dextroamphetamine, mixed amphetamine salts, and methylphenidate (all Schedule II controlled substances). (2) Narcolepsy — amphetamine salts and methylphenidate (modafinil is preferred first-line). (3) Short-term obesity management — phentermine and diethylpropion (amphetamine analogues)."]','A','Stimulants paradoxically calm children with ADHD — possibly by enhancing prefrontal cortex dopamine signalling, improving inhibitory control and attention. Atomoxetine (selective NE reuptake inhibitor) is a non-stimulant ADHD alternative and is not a controlled substance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','medium','flashcard','What is the mechanism of MDMA (ecstasy) and what is its most dangerous acute toxicity?','["MDMA causes massive release of serotonin, dopamine, and norepinephrine — with particularly profound serotonergic effects. The most dangerous acute toxicities: (1) severe hyperthermia from CNS stimulation and exertion in hot environments, (2) serotonin syndrome, and (3) hyponatraemia from excessive water drinking and SIADH-like effects."]','A','MDMA causes bruxism (teeth grinding) and trismus (jaw clenching). Cyproheptadine (oral serotonin antagonist) is used for serotonin syndrome. Life-threatening hyperthermia may require neuromuscular paralysis and intubation to control heat generation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','hard','flashcard','What is the mechanism of LSD and how does tolerance develop rapidly?','["LSD is a potent partial agonist at 5-HT2A serotonin receptors in the cerebral cortex — the primary mechanism for its profound hallucinogenic effects. Tolerance develops very rapidly (within days) via receptor down-regulation and desensitisation. Cross-tolerance exists between LSD and other serotonergic hallucinogens (psilocybin, mescaline)."]','A','LSD has essentially no physical dependence potential and extremely rare direct organ toxicity. Its dangers are primarily behavioural (impaired judgment, panic attacks, bad trips, trauma from impaired risk perception). Physical effects include mydriasis, tachycardia, and hyperthermia.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Pharmacology','Drugs of Abuse & CNS Stimulants','hard','flashcard','What are the three pharmacological treatment options for alcohol use disorder and their mechanisms?','["(1) Disulfiram — ALDH inhibitor, creates aversive acetaldehyde reaction if alcohol is consumed. (2) Naltrexone (oral daily or IM monthly depot) — opioid receptor antagonist, blocks endorphin-mediated alcohol reward and reduces craving. (3) Acamprosate — modulates NMDA and glutamate activity, reduces protracted withdrawal symptoms and craving. All require concurrent psychosocial support."]','A','Naltrexone is contraindicated in active opioid use (precipitates withdrawal) and significant hepatic impairment (hepatotoxicity risk). Acamprosate is renally excreted and safe in liver disease but avoided in severe renal impairment.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
